public:
    Grupo(Cupo cupo,Inscritos inscritos)
        : cupo_{cupo.personas},inscritos_{inscritos.personas} {
        if(cupo_<1 || cupo_>12 || inscritos_<0 || inscritos_>cupo_) {
            throw GrupoInvalido{};
        }
